import ARW_Support_3.Manager_Class as manimport osfrom pathlib import Path#-------------------------------------------------------------------------##----THIS IS CODE USED FOR LOADING AND PROCESSING IMAGES FROM A FOLDER----##-------------------------------------------------------------------------#os.chdir('/Users/akannan/Downloads/Lab/Proton-Computed-Tomography/')def get_image_names(folder_name: str) -> list:    base_dir = os.getcwd()    images_dir = os.path.join(base_dir, 'Images', 'ARW Files' ,folder_name)    # Create a list of all file names in the folder    image_names = os.listdir(images_dir)    return image_namesnames = get_image_names('Ce 140 MeV')names = sorted(names, key=lambda x: int(''.join(filter(str.isdigit, x))))Images = man.Manager()for name in names:    print(name)    title = name[:-4]    try:        img = Images.create_complete_image(name=title, filename=name, process=True)        img.crop_image(xstart=int(img.x_fit_params[1] - 5*img.x_fit_params[2]),                       xend=int(img.x_fit_params[1] + 5*img.x_fit_params[2]),                       ystart=int(img.y_fit_params[1] - 5*img.y_fit_params[2]),                       yend=int(img.y_fit_params[1] + 5*img.y_fit_params[2]))            except Exception as e:        print(f"[ERROR] {name}: {e}")        pass   good = list(Images.images.keys())print(f"GOODS: {good}")rejected = list(Images.review_images.keys())print(f"REJECTS: {rejected}")for name, Image in Images.images.items():    print(name)    Image.plot_gaussian(axis=0, fit=True, show=True, title = f"{name} x")    Image.plot_gaussian(axis=1, fit=True, show=True, title = f"{name} y")#---------To check potenitally bad images, include this block-----------#'''for name, Image in Images.review_images.items():    print(name)    Image.plot_2d()'''#-----------------------------------------------------## ---------- Input save location here ----------------##--------------------------------